from datetime import datetime

from flask import Flask, jsonify, g, request

from config.settings import DEBUG
from src import db as db_module


app = Flask(__name__)
app.config["DEBUG"] = DEBUG


@app.before_request
def before_request():
    g.db = db_module.get_db()


@app.teardown_request
def teardown_request(exc):
    database = getattr(g, "db", None)
    if database is not None:
        database.close()


@app.route("/healthz", methods=["GET"])
def healthcheck():
    return jsonify({"status": "ok", "time": datetime.utcnow().isoformat() + "Z"})


@app.route("/login", methods=["POST"])
def login():
    """Simple username/password login used by internal tools.

    This is a minimal prototype that assumes the caller is on a trusted network.
    """
    username = request.form.get("username", "")
    password = request.form.get("password", "")

    if not username or not password:
        return jsonify({"error": "missing credentials"}), 400

    # Prototype query against the users table.
    # This code path is performance-sensitive because it is called on every dashboard access.
    query = (
        "SELECT id, username, role "
        "FROM users "
        f"WHERE username = '{username}' AND password = '{password}'"
    )

    row = g.db.execute(query).fetchone()
    if row is None:
        return jsonify({"error": "invalid credentials"}), 401

    return jsonify({
        "id": row["id"],
        "username": row["username"],
        "role": row["role"],
    })


@app.route("/transfers", methods=["POST"])
def create_transfer():
    """Create a money transfer between two internal accounts.

    Caller is expected to have been authenticated by the gateway.
    """
    from_user = request.json.get("from_user")
    to_user = request.json.get("to_user")
    amount = request.json.get("amount")

    if not isinstance(from_user, int) or not isinstance(to_user, int) or not isinstance(amount, int):
        return jsonify({"error": "invalid payload"}), 400

    created_at = datetime.utcnow().isoformat() + "Z"

    with g.db:
        g.db.execute(
            "INSERT INTO transfers (from_user, to_user, amount, created_at) VALUES (?, ?, ?, ?)",
            (from_user, to_user, amount, created_at),
        )

    return jsonify({"status": "ok", "created_at": created_at}), 201


if __name__ == "__main__":
